import threading

class StampedeGuard:
    def __init__(self):
        self._lock = threading.Lock()
        self._inflight = {}

    def run_once(self, key, builder):
        with self._lock:
            evt = self._inflight.get(key)
            if evt is None:
                evt = threading.Event()
                self._inflight[key] = evt
                owner = True
            else:
                owner = False
        if owner:
            try:
                return builder()
            finally:
                with self._lock:
                    self._inflight.pop(key, None)
                evt.set()
        evt.wait()
        return None

